final class SimpleRouter {
    var path: [String] = []
    func push(_ s: String) { path.append(s) }
    func pop() { _ = path.popLast() }
}
let router = SimpleRouter()
router.push("feed")
router.push("profile")
router.pop()
print(router.path.count)

protocol FlowCoordinator: AnyObject {}
final class ChildFlow: FlowCoordinator {}
final class MainCoordinator {
    var children: [FlowCoordinator] = []
    func removeChild(_ child: FlowCoordinator) {
        children.removeAll { $0 === child }
    }
}
let main = MainCoordinator()
let c = ChildFlow()
main.children.append(c)
main.removeChild(c)
print(main.children.count)

final class StackRouter {
    var stack: [Int] = []
    func push(_ id: Int) { stack.append(id) }
    func popToRoot() { stack.removeAll() }
}
let router = StackRouter()
router.push(1)
router.push(2)
router.popToRoot()
print(router.stack.isEmpty)

