enum DeepLinkParser {
    static func parse(path: String) -> String {
        if path.hasPrefix("/product/") {
            let id = String(path.dropFirst("/product/".count))
            return "Product: \(id)"
        }
        return "Home"
    }
}
print(DeepLinkParser.parse(path: "/product/42"))

