final class MultiCoordinator {
    var children: [AnyObject] = []
    func add(_ child: AnyObject) { children.append(child) }
    func remove(_ child: AnyObject) { children.removeAll { $0 === child } }
}
final class SubFlow {}
let mc = MultiCoordinator()
let sf1 = SubFlow(), sf2 = SubFlow()
mc.add(sf1)
mc.add(sf2)
mc.remove(sf1)
print(mc.children.count)

